/* ReturnGuard: local-first, dependency-free browser application. */
(async function(){
  'use strict';
  const R=RG,E=R.escape,$=s=>document.querySelector(s),modal=$('#modal');
  const paths={shield:'M12 3 3 6v6c0 6 9 10 9 10s9-4 9-10V6Z M8 12l3 3 5-6',home:'m3 10 9-7 9 7v11h-6v-7H9v7H3Z',bag:'M5 7h14l2 14H3L5 7Z M8 8V6a4 4 0 0 1 8 0v2',receipt:'M5 3h14v19l-3-2-4 2-4-2-3 2V3Z M8 7h8 M8 11h8 M8 15h5',calendar:'M4 5h16v16H4Z M4 10h16 M8 3v4 M16 3v4',database:'M20 6c0 2-4 3-8 3S4 8 4 6s4-3 8-3 8 1 8 3Z M4 6v12c0 4 16 4 16 0V6 M4 12c0 4 16 4 16 0',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',close:'m6 6 12 12 M18 6 6 18',plus:'M12 5v14 M5 12h14',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',arrow:'M4 12h16 m-6-6 6 6-6 6',return:'M9 4 3 10l6 6 M3 10h11a7 7 0 0 1 0 14',lock:'M6 10h12v11H6Z M8 10V6a4 4 0 0 1 8 0v4',download:'M12 3v12 m-5-5 5 5 5-5 M4 16v5h16v-5',upload:'M12 16V4 m-5 5 5-5 5 5 M4 16v5h16v-5',image:'M3 3h18v18H3Z m0 14 6-6 5 5 3-3 4 4 M9 7h.01',edit:'m15 4 5 5 M4 16 17 3l4 4L8 20H4Z',trash:'M3 6h18 M8 6V3h8v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7',check:'m5 12 4 4L19 6',file:'M6 3h8l4 4v14H6Z M14 3v5h4 M9 12h6 M9 16h6',help:'M12 17h.01 M9 8a3 3 0 0 1 6 0c0 2-3 2-3 5 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0'};
  const icon=n=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[n]||paths.bag}"/></svg>`;
  let state={revision:0,purchases:[]},view='dashboard',query='',filter='all',status='all',sort='newest',calendarType='both',toastTimer,previousFocus,draft,blobUrls=[],pendingImport=null,storageReady=false,mutationBusy=false;
  const nav=[['dashboard','home','Dashboard'],['purchases','bag','All purchases'],['vault','receipt','Receipt vault'],['calendar','calendar','Calendar']];
  const btn=(text,action,kind='',ico='',extra='')=>`<button class="btn ${kind}" data-action="${action}" ${extra}>${ico?icon(ico):''}${text}</button>`;
  const photo=(p,extra='')=>p.photo?`<div class="product-photo ${extra}"><img src="${E(p.photo.data)}" alt="${E(p.name)}" loading="lazy"></div>`:`<div class="product-photo ${p.demoImage!==null&&p.demoImage!==undefined?'demo-photo p'+p.demoImage:''} ${extra}" role="img" aria-label="${E(p.name)}">${p.demoImage===null||p.demoImage===undefined?icon('bag'):''}${p.demo?'<span class="demo-label">DEMO</span>':''}</div>`;
  function toast(s){clearTimeout(toastTimer);$('#toast').textContent=s;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
  const find=id=>state.purchases.find(p=>p.id===id);
  const tag=p=>`<span class="status ${p.status.toLowerCase().replaceAll(' ','-')}">${p.status==='Keeping'?icon('check').replace('class="icon"','class="icon" style="width:11px;height:11px"'):''}${E(p.status)}</span>`;
  function openDialog(html){previousFocus=modal.open?previousFocus:document.activeElement;revokeUrls();modal.innerHTML=html;if(!modal.open)modal.showModal();requestAnimationFrame(()=>{const first=modal.querySelector('[autofocus]')||modal.querySelector('input,select,button');first?.focus();});}
  function closeDialog(){modal.close();revokeUrls();draft=null;pendingImport=null;previousFocus?.focus();}
  function revokeUrls(){blobUrls.forEach(URL.revokeObjectURL);blobUrls=[];}
  function head(title,sub=''){return `<div class="dialog-head"><div><h2 id="dialog-title">${title}</h2>${sub?`<p>${sub}</p>`:''}</div><button class="icon-btn" data-action="close" aria-label="Close dialog">${icon('close')}</button></div>`;}
  function errorText(err){return err?.name==='QuotaExceededError'?'Your browser storage is full. Export a backup, then remove unneeded attachments. Nothing was saved.':err?.message||'Something went wrong. Please try again.';}
  function showError(err){const target=modal.open?modal.querySelector('.error'):null;if(target){target.textContent=errorText(err);target.scrollIntoView({block:'nearest'});}else toast(errorText(err));}
  async function commit(items){if(!storageReady)throw Error('Storage is unavailable. Your changes cannot be saved.');if(mutationBusy)throw Error('A save is already in progress. Please wait.');if(new Blob([JSON.stringify(items)]).size>140*1024*1024)throw Error('The 140 MB local data limit is reached. Back up your data, then remove unneeded attachments.');mutationBusy=true;try{state=await RGStorage.write(items,state.revision);channel?.postMessage('updated');render();}finally{mutationBusy=false;}}
  let channel;try{channel=new BroadcastChannel('returnguard-changes');channel.onmessage=async()=>{if(!modal.open){state=await RGStorage.read();render();}else toast('Data changed in another tab. Refresh before saving.');};}catch{}
  function empty(title,text,buttons='',ico='bag'){return `<div class="empty"><div class="empty-icon">${icon(ico)}</div><h2>${title}</h2><p>${text}</p><div class="actions">${buttons}</div></div>`;}
  function render(){const st=R.stats(state.purchases);const titles={dashboard:['A little peace of mind.','Your purchases, protected. Your deadlines, handled.'],purchases:['Everything you brought home.','One thoughtful place for all your purchases.'],vault:['Your paperwork, in order.','Receipts and invoices. Right where you need them.'],calendar:['Stay one step ahead.','Your return and warranty dates, clearly separated.'],data:['Yours to keep. Yours to control.','Your data stays on this device. Make a backup for peace of mind.']};
    $('#app').innerHTML=`<aside class="sidebar"><div class="brand"><span class="brand-mark">${icon('shield')}</span>ReturnGuard</div><nav class="nav" aria-label="Main navigation">${nav.map(([v,i,t])=>`<button data-view="${v}" class="${view===v?'active':''}" ${view===v?'aria-current="page"':''}>${icon(i)}${t}</button>`).join('')}</nav><div class="sidebar-bottom"><button class="data-nav ${view==='data'?'active':''}" data-view="data" ${view==='data'?'aria-current="page"':''}>${icon('database')}Backup & data</button><div class="storage"><span class="dot"></span><div><strong>${storageReady?'Saved on this device':'Storage unavailable'}</strong><small>Private by design</small></div></div></div></aside><main id="main" class="main"><div class="mobile-brand">${icon('shield')}ReturnGuard</div><header class="page-head"><div><h1>${titles[view][0]}</h1><p>${titles[view][1]}</p></div>${['dashboard','purchases'].includes(view)?btn('Add purchase','add','primary','plus'):view==='vault'?btn('Upload receipt','upload-receipt','primary','upload'):''}</header><div id="view-content">${view==='dashboard'?dashboard(st):view==='purchases'?purchases():view==='vault'?vault():view==='calendar'?calendar():dataPage()}</div><footer class="footer"><span>${icon('lock')}Private by design. Saved in this browser.</span><button class="btn quiet" data-action="help">A little help ${icon('help')}</button><span>Made for a little less worry.</span></footer></main>`;
  }
  function summary(st){return `<div class="summary">${[['active','bag','Active purchases',st.active],['soon','clock','Due in 7 days',st.soon],['expired','close','Return window closed',st.expired],['warranty','shield','Under warranty',st.warranty]].map(([f,i,t,n])=>`<button class="metric" data-filter-nav="${f}" aria-label="${t}: ${n}">${icon(i)}<div><span class="metric-label">${t}</span><strong>${n}</strong></div></button>`).join('')}</div>`;}
  function dashboard(st){return summary(st)+(st.soon?`<div class="deadline-banner">${icon('clock')}<div><strong>A decision worth making.</strong><p>${st.soon} return window${st.soon===1?'':'s'} close${st.soon===1?'s':''} this week.</p></div>${btn('Review deadlines','review','primary small','arrow')}</div>`:'')+demoNotice()+purchaseSection(true)+upcoming();}
  function demoNotice(){return state.purchases.some(p=>p.demo)?`<div class="demo-notice"><span>You're viewing example purchases. Demo dates are fictional, not store policies.</span>${btn('Remove demo','remove-demo','quiet small')}</div>`:'';}
  function purchases(){return demoNotice()+purchaseSection(false);}
  function purchaseSection(dashboardView){return `<section aria-label="Purchases"><div class="section-heading"><h2>Your purchases</h2><label class="search">${icon('search')}<span class="sr-only">Search purchases</span><input id="search" type="search" placeholder="Search products or stores" value="${E(query)}" autocomplete="off"></label></div><div class="toolbar"><div class="chips" aria-label="Filter purchases">${[['all','All'],['soon','Return soon'],['warranty','Warranty'],...(!dashboardView?[['expired','Expired'],['active','Active']]:[])].map(([v,l])=>`<button class="chip ${filter===v?'selected':''}" data-filter="${v}" aria-pressed="${filter===v}">${l}${v==='all'?` <span>(${state.purchases.length})</span>`:''}</button>`).join('')}</div><div class="toolbar-right"><select id="status-filter" aria-label="Filter by status"><option value="all">All statuses</option>${R.STATUSES.map(s=>`<option ${s===status?'selected':''}>${s}</option>`).join('')}</select><select id="sort" aria-label="Sort purchases">${[['newest','Newest purchases'],['oldest','Oldest purchases'],['return','Return deadline'],['warranty','Warranty expiration'],['name','Product name']].map(([v,l])=>`<option value="${v}" ${sort===v?'selected':''}>${l}</option>`).join('')}</select></div></div><div id="purchase-results">${results(dashboardView)}</div></section>`;}
  function results(dashboardView=view==='dashboard'){if(!state.purchases.length)return empty('Make room for peace of mind.','Add your first purchase to keep its return date, warranty, and receipt together. No more searching through your inbox.',btn('Add your first purchase','add','primary','plus')+btn('Explore with demo data','demo','', 'arrow'),'bag');
    let list=R.filter(state.purchases,{search:query,filter,status,sort});if(!list.length)return empty('Nothing here just yet.','Try another search or clear your filters to see all purchases.',btn('Clear filters','clear-filters'),'search');const total=list.length;if(dashboardView)list=list.slice(0,3);return `<div class="cards">${list.map(card).join('')}</div><div class="filter-count">${dashboardView&&total>3?`Showing 3 of ${total} purchases ${btn('View all purchases','view-all','quiet small','arrow')}`:`${total} purchase${total===1?'':'s'}`}</div>`;}
  function card(p){const n=p.returnDate?R.days(p.returnDate):null;const tone=n===null?'':n<0?'expired':n<=7?'urgent':'';const range=p.returnDate?Math.max(1,R.days(p.returnDate,p.purchaseDate)):1;const progress=n===null?0:Math.max(0,Math.min(100,n/range*100));return `<article class="product-card" data-id="${p.id}"><button class="product-photo" data-action="details" data-id="${p.id}" aria-label="View ${E(p.name)}">${photo(p)}</button><div class="card-content"><div class="card-title"><button class="title-button" data-action="details" data-id="${p.id}"><h3>${E(p.name)}</h3></button><button class="icon-btn" data-action="edit" data-id="${p.id}" aria-label="Edit ${E(p.name)}">${icon('edit')}</button></div><div class="card-store"><span>${E(p.store)}</span><strong>${E(R.money(p))}</strong></div>${tag(p)}<div class="card-dates"><div class="date-row"><span>${icon('return')}Return window</span><strong class="${R.active(p)?tone:''}">${R.active(p)?R.countdown(p.returnDate):'Return completed'}</strong></div><div class="date-row"><span>${icon('shield')}Warranty expires</span><span>${R.date(p.warrantyDate)}</span></div></div><div class="progress ${tone}" aria-hidden="true"><span style="width:${progress}%"></span></div></div></article>`;}
  function upcoming(){const list=R.events(state.purchases,'return').slice(0,3);return list.length?`<section class="upcoming"><div class="section-heading"><h2>Upcoming deadlines</h2>${btn('View calendar','calendar','quiet small','arrow')}</div><div class="list">${list.map(e=>`<div class="list-row"><div class="thumb">${e.purchase.photo?`<img src="${E(e.purchase.photo.data)}" alt="">`:icon('bag')}</div><div class="row-info"><strong>${E(e.purchase.name)}</strong><p>${E(e.purchase.store)} · ${E(R.money(e.purchase))}</p></div><span class="deadline-pill">${R.countdown(e.date)}</span><span class="row-date">${R.date(e.date)}</span><button class="btn small" data-action="details" data-id="${e.purchase.id}"><span>View purchase</span>${icon('arrow')}</button></div>`).join('')}</div></section>`:'';}
  function vault(){const files=state.purchases.flatMap(p=>p.receipts.map(f=>({p,f}))).filter(({p,f})=>(p.name+' '+p.store+' '+f.name).toLowerCase().includes(query.toLowerCase()));return `<div class="section-heading"><h2>Receipt vault <span class="muted small">${state.purchases.reduce((n,p)=>n+p.receipts.length,0)} files</span></h2><label class="search">${icon('search')}<span class="sr-only">Search receipts</span><input id="receipt-search" type="search" placeholder="Search receipts or purchases" value="${E(query)}"></label></div><div id="vault-results">${files.length?`<div class="receipt-grid">${files.map(({p,f})=>`<article class="receipt-card"><button class="receipt-preview" data-action="view-receipt" data-id="${p.id}" data-file="${f.id}" aria-label="View ${E(f.name)}">${f.type.startsWith('image/')?`<img src="${E(f.data)}" alt="${E(f.name)}" loading="lazy">`:icon('receipt')}</button><div class="receipt-content"><h3>${E(f.name)}</h3><p>${E(p.name)} · ${E(p.store)}</p><div class="actions">${btn('View receipt','view-receipt','small','','data-id="'+p.id+'" data-file="'+f.id+'"')}<button class="icon-btn" data-action="delete-receipt" data-id="${p.id}" data-file="${f.id}" aria-label="Delete ${E(f.name)}">${icon('trash')}</button></div></div></article>`).join('')}</div>`:empty(query?'No matching receipts.':'Goodbye, paper trail.','Keep your receipts and invoices alongside the purchases they belong to. PDF, PNG, JPEG, and WebP files are supported.',btn('Upload a receipt','upload-receipt','primary','upload'),'receipt')}</div>`;}
  function calendar(){const events=R.events(state.purchases,calendarType);let month='';return `<div class="intro-note">Dates come from your entries, never guessed store policies. Calendar downloads include an all-day event and a reminder one day before. Import the file into your calendar to activate reminders.</div><div class="calendar-controls"><label class="field"><span class="sr-only">Deadline type</span><select id="calendar-type"><option value="both" ${calendarType==='both'?'selected':''}>Returns & warranties</option><option value="return" ${calendarType==='return'?'selected':''}>Return deadlines</option><option value="warranty" ${calendarType==='warranty'?'selected':''}>Warranty expirations</option></select></label>${btn(`Export ${events.length} reminder${events.length===1?'':'s'} (.ics)`,'export-calendar','primary','download',events.length?'':'disabled')}</div>${events.length?events.map(e=>{const m=e.date.slice(0,7);const heading=m!==month?`<h2 class="calendar-month">${new Date(e.date+'T12:00:00').toLocaleDateString('en-US',{month:'long',year:'numeric'})}</h2>`:'';month=m;return heading+`<div class="list-row"><div class="event-day"><strong>${Number(e.date.slice(-2))}</strong><small>${new Date(e.date+'T12:00:00').toLocaleDateString('en-US',{weekday:'short'})}</small></div><div class="row-info"><strong>${E(e.purchase.name)}</strong><p>${e.type==='return'?'Return deadline':'Warranty expiration'} · ${E(e.purchase.store)}</p></div><span class="deadline-pill">${R.days(e.date)===0?'Today':`In ${R.days(e.date)} days`}</span>${btn('View purchase','details','small','arrow','data-id="'+e.purchase.id+'"')}</div>`;}).join(''):empty('A clear calendar.','Add a return deadline or warranty expiration to a purchase to see it here. Past dates and completed returns are excluded.',btn('View purchases','view-all','','bag'),'calendar')}`;}
  function dataPage(){return `<div class="data-grid"><section class="data-card">${icon('download')}<h2>A copy for safekeeping.</h2><p>Download all ${state.purchases.length} purchases, including their photos and receipts, in one portable JSON file. Keep it somewhere safe.</p>${btn('Export backup','backup','primary','download')}</section><section class="data-card">${icon('upload')}<h2>Bring everything back.</h2><p>Restore a ReturnGuard backup on this browser or a new device. Preview its contents before merging or replacing your data.</p><label class="field"><span>Choose a ReturnGuard backup</span><input type="file" id="import-file" accept=".json,application/json"></label></section><section class="data-card wide">${icon('lock')}<h2>Private means private.</h2><p>Your purchases and attachments are saved in this browser using IndexedDB. There is no account sync, analytics, or file upload to a server. Different browsers and different app addresses keep separate data. Clearing browser data or using private browsing can erase your records. Back up regularly; backup files contain your personal information and are not encrypted.</p><div class="actions">${btn('Try demo purchases','demo','','bag',state.purchases.some(p=>p.demo)?'disabled':'')}${state.purchases.some(p=>p.demo)?btn('Remove demo purchases','remove-demo','quiet'):''}${btn('Delete all local data','clear-data','danger','trash',state.purchases.length?'':'disabled')}</div></section></div>`;}
  function input(label,name,value='',type='text',extra=''){return `<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${E(value)}" ${extra}></label>`;}
  function editPurchase(id){const existing=find(id);draft=existing?structuredClone(existing):{id:R.id(),name:'',store:'',price:'',currency:'USD',purchaseDate:R.today(),returnDate:'',warrantyDate:'',status:'Keeping',notes:'',photo:null,receipts:[],demo:false,demoImage:null};const p=draft;
    openDialog(`<form id="purchase-form">${head(existing?'Edit purchase':'Add a purchase','A few details now. Peace of mind later.')}<div class="dialog-body"><div class="photo-upload"><div class="thumb" id="photo-preview">${p.photo?`<img src="${E(p.photo.data)}" alt="Product photo">`:icon('image')}</div><label class="field"><span>Product photo <small>optional</small></span><input id="photo-file" type="file" accept="image/png,image/jpeg,image/webp"><span class="help">PNG, JPEG or WebP · up to 8 MB</span></label><button type="button" class="icon-btn" data-action="remove-photo" aria-label="Remove product photo">${icon('trash')}</button></div><div class="form-grid"><div class="wide">${input('Product name *','name',p.name,'text','required maxlength="160" placeholder="e.g. Studio Headphones" autofocus')}</div>${input('Store *','store',p.store,'text','required maxlength="160" placeholder="Where did you buy it?"')}${input('Price *','price',p.price,'number','required min="0" max="999999999" step="0.01" placeholder="0.00"')}<label class="field"><span>Currency *</span><select name="currency">${R.CURRENCIES.map(c=>`<option ${c===p.currency?'selected':''}>${c}</option>`).join('')}</select></label>${input('Purchase date *','purchaseDate',p.purchaseDate,'date','required min="1900-01-01" max="2200-12-31"')}<div class="date-fields wide">${input('Return deadline <small>optional</small>','returnDate',p.returnDate,'date','min="1900-01-01" max="2200-12-31"')}${input('Warranty expiration <small>optional</small>','warrantyDate',p.warrantyDate,'date','min="1900-01-01" max="2200-12-31"')}<p class="help wide">Enter dates from your receipt or store policy. We never guess. Leave unknown dates blank.</p></div><label class="field wide"><span>Return status</span><select name="status">${R.STATUSES.map(s=>`<option ${s===p.status?'selected':''}>${s}</option>`).join('')}</select></label><label class="field wide"><span>Receipts & invoices <small>optional</small></span><input id="receipt-files" type="file" multiple accept="application/pdf,image/png,image/jpeg,image/webp"><span class="help">PDF, PNG, JPEG or WebP · up to 12 MB each · 30 per purchase</span></label><div id="draft-files" class="wide"></div><label class="field wide"><span>Notes <small>optional</small></span><textarea name="notes" maxlength="5000" placeholder="Order number, warranty details, or a note to yourself…">${E(p.notes)}</textarea></label></div><p class="error" role="alert"></p></div><div class="dialog-footer"><button type="button" class="btn" data-action="close">Cancel</button><button type="submit" class="btn primary" id="save-purchase">Save purchase</button></div></form>`);renderDraftFiles();
  }
  function renderDraftFiles(){if(!draft||!$('#draft-files'))return;$('#draft-files').innerHTML=draft.receipts.length?`<div class="file-list">${draft.receipts.map(f=>`<div class="file-item">${icon('file')}<span>${E(f.name)}</span><button type="button" class="icon-btn" data-action="remove-draft-file" data-file="${f.id}" aria-label="Remove ${E(f.name)}">${icon('close')}</button></div>`).join('')}</div>`:'';}
  function details(id){const p=find(id);if(!p)return;openDialog(`${head(E(p.name),E(p.store)+' · '+E(R.money(p)))}<div class="dialog-body">${photo(p,'details-photo')}<div class="details-title">${tag(p)}${p.demo?'<span class="help">Example purchase</span>':''}</div><dl class="detail-grid"><div><dt>Purchased</dt><dd>${R.date(p.purchaseDate)}</dd></div><div><dt>Price</dt><dd>${E(R.money(p))}</dd></div><div><dt>Return deadline</dt><dd>${R.date(p.returnDate)}<p class="help">${R.active(p)?R.countdown(p.returnDate):'Return completed'}</p></dd></div><div><dt>Warranty expiration</dt><dd>${R.date(p.warrantyDate)}<p class="help">${!p.warrantyDate?'No date entered':R.days(p.warrantyDate)<0?'Expired':R.days(p.warrantyDate)===0?'Expires today':R.days(p.warrantyDate)+' days remaining'}</p></dd></div></dl><label class="field"><span>Return status</span><select id="quick-status" data-id="${p.id}">${R.STATUSES.map(s=>`<option ${s===p.status?'selected':''}>${s}</option>`).join('')}</select></label>${p.notes?`<p class="details-notes">${E(p.notes)}</p>`:''}<h3 style="margin-top:24px">Receipts & invoices <span class="muted small">(${p.receipts.length})</span></h3><div class="file-list">${p.receipts.map(f=>`<div class="file-item">${icon('file')}<span>${E(f.name)}</span>${btn('View','view-receipt','small','','data-id="'+p.id+'" data-file="'+f.id+'"')}</div>`).join('')||'<p class="help">No receipts yet. Edit this purchase to attach one.</p>'}</div><p class="error" role="alert"></p></div><div class="dialog-footer">${btn('Delete','delete','danger','trash','data-id="'+p.id+'"')}${btn('Calendar (.ics)','purchase-calendar','','calendar','data-id="'+p.id+'" '+(R.events([p]).length?'':'disabled'))}${btn('Edit purchase','edit','primary','edit','data-id="'+p.id+'"')}</div>`);}
  function confirmDialog(title,text,action,label='Confirm',extra=''){openDialog(`${head(title)}<div class="dialog-body"><p class="small muted">${text}</p><p class="error" role="alert"></p></div><div class="dialog-footer">${btn('Cancel','close')}${btn(label,action,'danger','',extra)}</div>`);}
  function download(content,name,type){const url=URL.createObjectURL(content instanceof Blob?content:new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
  function fileBlob(f){const data=atob(f.data.split(',')[1]);const bytes=Uint8Array.from(data,c=>c.charCodeAt(0));return new Blob([bytes],{type:f.type});}
  function viewReceipt(id,fid){const p=find(id),f=p?.receipts.find(f=>f.id===fid);if(!f)return;openDialog(`${head(E(f.name),E(p.name))}<div class="dialog-body" id="receipt-viewer"></div><div class="dialog-footer">${btn('Back to purchase','details','','','data-id="'+p.id+'"')}${btn('Download receipt','download-receipt','primary','download','data-id="'+p.id+'" data-file="'+f.id+'"')}</div>`);if(f.type==='application/pdf'){const url=URL.createObjectURL(fileBlob(f));blobUrls.push(url);$('#receipt-viewer').innerHTML=`<iframe class="view-pdf" title="PDF receipt preview" src="${url}"></iframe><p class="help">If your browser cannot preview this PDF, use Download receipt to open it.</p>`;}else $('#receipt-viewer').innerHTML=`<img class="view-image" src="${E(f.data)}" alt="${E(f.name)}">`;}
  async function readFile(file,photoFile=false){if(!file.size)throw Error('This file is empty.');if(file.size>(photoFile?8:12)*1024*1024)throw Error(`${file.name} is too large. Limit: ${photoFile?8:12} MB.`);const data=await new Promise((res,rej)=>{const reader=new FileReader();reader.onload=()=>res(reader.result);reader.onerror=()=>rej(Error('Could not read this file. Please try again.'));reader.readAsDataURL(file);});const f=R.validateAsset({id:R.id(),name:file.name,data},photoFile);if(f.type.startsWith('image/'))await new Promise((res,rej)=>{const img=new Image();img.onload=()=>{if(img.naturalWidth*img.naturalHeight>50000000)rej(Error('This image is too large to display safely. Resize it below 50 megapixels.'));else res();};img.onerror=()=>rej(Error('This image could not be opened. Choose a valid PNG, JPEG or WebP.'));img.src=data;});return f;}
  function uploadReceipt(){if(!state.purchases.length){toast('Add a purchase first, then attach its receipt.');editPurchase();return;}openDialog(`<form id="vault-form">${head('Add to your receipt vault','Attach receipts or invoices to a purchase.')}<div class="dialog-body"><div class="form-grid"><label class="field wide"><span>Purchase</span><select name="purchaseId">${state.purchases.map(p=>`<option value="${p.id}">${E(p.name)} — ${E(p.store)}</option>`).join('')}</select></label><label class="field wide"><span>Receipt files</span><input required type="file" name="files" multiple accept="application/pdf,image/png,image/jpeg,image/webp"><span class="help">PDF, PNG, JPEG, WebP · up to 12 MB each</span></label></div><p class="error" role="alert"></p></div><div class="dialog-footer"><button type="button" class="btn" data-action="close">Cancel</button><button type="submit" class="btn primary">Save receipts</button></div></form>`);}
  function importPreview(list){pendingImport=list;openDialog(`${head('Your backup is ready to restore.',`${list.length} purchases · ${list.reduce((n,p)=>n+p.receipts.length,0)} receipts`)}<div class="dialog-body"><p class="small muted">Choose how this backup should be applied. Nothing changes until you select Import backup.</p><label class="check-label"><input type="radio" name="import-mode" value="merge" checked><span><strong>Merge with current purchases</strong><br>Keep existing purchases. Add only records with new IDs; matching IDs are skipped.</span></label><label class="check-label"><input type="radio" name="import-mode" value="replace"><span><strong>Replace all local purchases</strong><br>Remove the current ${state.purchases.length} purchases and restore this backup instead. Export your current data first if you need it.</span></label><p class="error" role="alert"></p></div><div class="dialog-footer">${btn('Cancel','close')}${btn('Import backup','confirm-import','primary','upload')}</div>`);}
  function navigate(v){view=v;query='';filter='all';status='all';render();window.scrollTo(0,0);}
  async function act(action,el){const id=el.dataset.id,p=find(id),fid=el.dataset.file;switch(action){
    case 'add':editPurchase();break;case 'edit':editPurchase(id);break;case 'details':details(id);break;case 'close':closeDialog();break;
    case 'view-all':navigate('purchases');break;case 'calendar':navigate('calendar');break;
    case 'review':navigate('purchases');filter='soon';sort='return';render();break;
    case 'clear-filters':query='';filter='all';status='all';render();break;
    case 'demo':if(state.purchases.some(p=>p.demo))return toast('Demo purchases are already loaded.');await commit([...state.purchases,...R.demo()]);toast('Demo purchases added. All example dates are fictional.');break;
    case 'remove-demo':confirmDialog('Remove example purchases?','This removes only purchases marked as demo and any receipts attached to them. Your own purchases stay in place.','confirm-remove-demo','Remove demo');break;
    case 'confirm-remove-demo':await commit(state.purchases.filter(p=>!p.demo));closeDialog();toast('Demo purchases removed.');break;
    case 'delete':confirmDialog('Delete this purchase?',`${E(p.name)} and its attached receipts will be permanently removed from this browser.`,'confirm-delete','Delete purchase','data-id="'+id+'"');break;
    case 'confirm-delete':await commit(state.purchases.filter(p=>p.id!==id));closeDialog();toast('Purchase deleted.');break;
    case 'remove-photo':draft.photo=null;draft.demoImage=null;$('#photo-preview').innerHTML=icon('image');$('#photo-file').value='';break;
    case 'remove-draft-file':draft.receipts=draft.receipts.filter(f=>f.id!==fid);renderDraftFiles();break;
    case 'upload-receipt':uploadReceipt();break;
    case 'view-receipt':viewReceipt(id,fid);break;
    case 'download-receipt':{const f=p.receipts.find(f=>f.id===fid);download(fileBlob(f),f.name,f.type);toast('Receipt download prepared.');break;}
    case 'delete-receipt':confirmDialog('Delete this receipt?',`${E(p.receipts.find(f=>f.id===fid).name)} will be removed. The purchase stays in your tracker.`,'confirm-delete-receipt','Delete receipt',`data-id="${id}" data-file="${fid}"`);break;
    case 'confirm-delete-receipt':await commit(state.purchases.map(p=>p.id===id?{...p,receipts:p.receipts.filter(f=>f.id!==fid)}:p));closeDialog();toast('Receipt deleted.');break;
    case 'export-calendar':case 'purchase-calendar':{const items=action==='purchase-calendar'?[p]:state.purchases;const type=action==='purchase-calendar'?'both':calendarType;if(!R.events(items,type).length)return toast('No upcoming dates to export.');download(R.calendar(items,type),'ReturnGuard-reminders.ics','text/calendar;charset=utf-8');toast('Calendar file ready. Import it into your calendar app.');break;}
    case 'backup':download(JSON.stringify({app:'ReturnGuard',version:1,exportedAt:new Date().toISOString(),purchases:state.purchases},null,2),`ReturnGuard-backup-${R.today()}.json`,'application/json');toast('Backup download prepared, including photos and receipts.');break;
    case 'confirm-import':{const mode=modal.querySelector('[name=import-mode]:checked').value;const ids=new Set(state.purchases.map(p=>p.id));const add=pendingImport.filter(p=>!ids.has(p.id));const next=mode==='replace'?pendingImport:[...state.purchases,...add];if(next.length>5000)throw Error('A maximum of 5,000 purchases is supported.');await commit(next);closeDialog();toast(mode==='replace'?'Backup restored.':`${add.length} purchases imported. Matching IDs were kept unchanged.`);break;}
    case 'clear-data':confirmDialog('Delete all local data?','All purchases, photos, and receipts in this browser will be permanently deleted. Export a backup first if you want to keep a copy.','confirm-clear-data','Delete all local data');break;
    case 'confirm-clear-data':await commit([]);closeDialog();toast('All local data deleted.');break;
    case 'help':openDialog(`${head('A little help.')}<div class="dialog-body"><div class="intro-note"><strong>1. Add your purchase.</strong><br>Enter the product, store, price, and purchase date.<br><br><strong>2. Confirm your dates.</strong><br>Find return and warranty dates on your receipt or store policy. Leave unknown dates empty. ReturnGuard does not determine eligibility or invent policies.<br><br><strong>3. Keep your receipt close.</strong><br>Upload images or PDF files to the purchase or Receipt vault.<br><br><strong>4. Set a reminder.</strong><br>Export an .ics file from Calendar, then import it into Apple Calendar, Google Calendar, or Outlook. Your calendar handles alerts; ReturnGuard itself does not send notifications.<br><br><strong>5. Make a backup.</strong><br>Use Backup & data to export your purchases and attachments. Data does not sync across browsers or devices.</div><p class="small muted">Return counts exclude Returned and Refunded purchases. Deadline dates are inclusive, use your device's local date, and do not imply a store's cutoff time. Warranty countdowns track your entered expiration date, not coverage eligibility. Supported prices are stored in each purchase's selected currency, without conversion.</p></div><div class="dialog-footer">${btn('Got it','close','primary')}</div>`);break;
  }}
  document.addEventListener('click',async e=>{const el=e.target.closest('button');if(!el||el.disabled)return;try{if(el.dataset.view){navigate(el.dataset.view);return;}if(el.dataset.filterNav){navigate('purchases');filter=el.dataset.filterNav;render();return;}if(el.dataset.filter){filter=el.dataset.filter;render();return;}if(el.dataset.action){if(el.closest('form'))e.preventDefault();el.disabled=true;try{await act(el.dataset.action,el);}finally{if(el.isConnected)el.disabled=false;}}}catch(err){showError(err);}});
  document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;$('#purchase-results').innerHTML=results();}if(e.target.id==='receipt-search'){query=e.target.value;const box=document.createElement('div');box.innerHTML=vault();$('#vault-results').innerHTML=box.querySelector('#vault-results').innerHTML;}});
  let fileBusy=false;
  document.addEventListener('change',async e=>{const el=e.target;try{
    if(el.id==='status-filter'){status=el.value;$('#purchase-results').innerHTML=results();}
    else if(el.id==='sort'){sort=el.value;$('#purchase-results').innerHTML=results();}
    else if(el.id==='calendar-type'){calendarType=el.value;render();}
    else if(el.id==='quick-status'){el.disabled=true;try{await commit(state.purchases.map(p=>p.id===el.dataset.id?{...p,status:el.value}:p));details(el.dataset.id);toast('Status saved.');}catch(err){el.value=find(el.dataset.id).status;throw err;}finally{el.disabled=false;}}
    else if(el.id==='photo-file'||el.id==='receipt-files'){if(!el.files.length)return;fileBusy=true;const currentDraft=draft;$('#save-purchase').disabled=true;try{if(el.id==='photo-file'){const f=await readFile(el.files[0],true);if(draft!==currentDraft)return;draft.photo=f;draft.demoImage=null;$('#photo-preview').innerHTML=`<img src="${E(f.data)}" alt="Product photo">`;}else{if(draft.receipts.length+el.files.length>30)throw Error('A purchase can contain up to 30 receipts.');const files=await Promise.all([...el.files].map(f=>readFile(f)));if(draft!==currentDraft)return;draft.receipts.push(...files);renderDraftFiles();}el.value='';}finally{fileBusy=false;if($('#save-purchase'))$('#save-purchase').disabled=false;}}
    else if(el.id==='import-file'){const file=el.files[0];if(!file)return;el.value='';if(file.size>150*1024*1024)throw Error('This backup is larger than the 150 MB import limit.');let parsed;try{parsed=JSON.parse(await file.text());}catch{throw Error('This file is not valid JSON. Choose a ReturnGuard backup.');}const list=R.validateBackup(parsed);importPreview(list);}
  }catch(err){showError(err);}});
  document.addEventListener('submit',async e=>{if(!['purchase-form','vault-form'].includes(e.target.id))return;e.preventDefault();const form=e.target,submit=form.querySelector('[type=submit]');if(fileBusy)return;submit.disabled=true;form.querySelector('.error').textContent='';try{if(form.id==='purchase-form'){const values=Object.fromEntries(new FormData(form));const p=R.validatePurchase({...draft,...values,price:Number(values.price)});if(!find(p.id)&&state.purchases.length>=5000)throw Error('A maximum of 5,000 purchases is supported.');await commit(find(p.id)?state.purchases.map(x=>x.id===p.id?p:x):[p,...state.purchases]);query='';filter='all';status='all';sort='newest';render();closeDialog();toast('Purchase saved. A little less to remember.');}else{const id=form.elements.purchaseId.value;const p=find(id);if(form.elements.files.files.length+p.receipts.length>30)throw Error('A purchase can contain up to 30 receipts.');const files=await Promise.all([...form.elements.files.files].map(f=>readFile(f)));await commit(state.purchases.map(p=>p.id===id?{...p,receipts:[...p.receipts,...files]}:p));closeDialog();toast(`${files.length} receipt${files.length===1?'':'s'} saved.`);}}catch(err){showError(err);}finally{if(submit.isConnected)submit.disabled=false;}});
  modal.addEventListener('cancel',e=>{e.preventDefault();closeDialog();});
  try{await RGStorage.open();state=await RGStorage.read();storageReady=true;render();}catch(err){render();$('#view-content').innerHTML=empty('Your browser storage is unavailable.','Open ReturnGuard in a regular Chrome, Edge, Safari, or Firefox window with site storage enabled. Your existing data has not been changed.',btn('Try again','reload','primary'),'lock');document.addEventListener('click',e=>{if(e.target.closest('[data-action=reload]'))location.reload();});toast(errorText(err));}
  let lastDay=R.today();setInterval(async()=>{if(R.today()!==lastDay){lastDay=R.today();render();}},60000);
  document.addEventListener('visibilitychange',async()=>{if(!document.hidden&&storageReady&&!modal.open){try{state=await RGStorage.read();render();}catch{toast('Could not refresh local data. Reload the page.');}}});
})();
